.upload_img{
	padding: 0 15px;
	&.on{
		.title{
			margin-bottom: 0;
			padding-bottom 0;
		}
		.list{
			padding: 0;
			height: auto;
			background: #fff;
			padding-bottom:20px;
			.box{
				margin-bottom: 0;
			}
			.name{
				width: 75px;
			}
		}
	}
	.list{
		width: 370px;
		height: 137px;
		background: #F9F9F9;
		border-radius: 3px;
		padding: 16px 20px;
	}
	.item{
		display: flex;
		align-items: center;
		.name{
			font-size: 12px;
			color: #999999;
			margin-right: 16px;
		}
		/deep/.ivu-input-icon{
			color: #BBBBBB;
		}
		.picTxt{
			display: flex;
			align-items: center;
			.tip{
				color: #BBBBBB;
				font-size: 12px;
				margin-left: 20px;
			}
		}
	}
}
.header{
    font-size 14px
    color #000
}
.title{
    margin-bottom: 10px;
    padding-bottom 10px;
    font-size:12px;
    color:#999;
}
.box{
	width 64px
	height 64px
	margin-bottom 10px
	position relative
	background url(../../assets/images/transparents.jpg) no-repeat
	background-size 100% 100%;
	border-radius: 3px;
	.pictrue{
		position: relative;
		width: 100%;
		height: 100%;
		video{
			width: 100%;
			height: 100%;
		}
		.iconfont{
			position: absolute;
			right:-12px;
			top:-19px;
			font-size: 24px;
			color: #CCCCCC;
		}
	}
	img{
		width 64px
		border-radius: 3px;
		max-height: 64px;
		object-fit: cover;
	}
}

.upload-box{
	display flex
	align-items center
	justify-content center
	width 64px
	height 64px
	background #fff
	border-radius: 4px;
	border: 1px solid #EEEEEE;
	.ivu-icon{
		color: #ccc
	}
}
